#!/usr/bin/env sh
# Generates secrets.h from environment variables at build time.
# Unset/empty vars produce empty string literals, so the bound keys send nothing.
# The generated file is gitignored and must never be committed.
set -eu

out="$(dirname "$0")/secrets.h"

# Escape a raw value into a safe C string literal body: backslash first, then quote.
esc() {
    printf '%s' "${1-}" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g'
}

{
    echo '// AUTO-GENERATED by gen_secrets.sh - do not edit, do not commit.'
    echo '#pragma once'
    printf '#define USER_PW03 "%s"\n'        "$(esc "${WINRY_PW03-}")"
    printf '#define USER_PW04 "%s"\n'        "$(esc "${WINRY_PW04-}")"
    printf '#define USER_PW_FALLBACK "%s"\n' "$(esc "${WINRY_PW_FALLBACK-}")"
} > "$out"
